local seq = Instance.new("KeyframeSequence")
seq.Name, seq.Loop, seq.Priority = NAME, LOOP, PRIORITY
if HIP then pcall(function() seq.AuthoredHipHeight = HIP end) end
for fi, f in ipairs(FRAMES) do
	local kf = Instance.new("Keyframe")
	kf.Time = f[1]
	if KEYNAMES[fi] then kf.Name = KEYNAMES[fi] end
	local made, k = {}, 2
	for i, d in ipairs(POSES) do
		local pose = Instance.new("Pose")
		pose.Name, pose.Weight, pose.EasingStyle = d[1], d[3], Enum.PoseEasingStyle.Linear
		if d[3] > 0 then
			pose.CFrame = CFrame.new(f[k], f[k + 1], f[k + 2], f[k + 3], f[k + 4], f[k + 5], f[k + 6])
			k += 7
		end
		if d[2] == 0 then kf:AddPose(pose) else made[d[2]]:AddSubPose(pose) end
		made[i] = pose
	end
	for _, m in ipairs(MARKERS) do
		if m[1] == fi then
			local marker = Instance.new("KeyframeMarker")
			marker.Name, marker.Value = m[2], m[3]
			kf:AddMarker(marker)
		end
	end
	seq:AddKeyframe(kf)
end
local Selection = game:GetService("Selection")
local rig = Selection:Get()[1]
local saves = rig and rig:FindFirstChild("AnimSaves")
local home = saves and (saves:IsA("ObjectValue") and saves.Value or saves) or game:GetService("ServerStorage")
local old = home:FindFirstChild(NAME)
if old and old:IsA("KeyframeSequence") then old:Destroy() end
seq.Parent = home
Selection:Set({seq})
print(("[animation] %s: %d keyframes, %.2fs -> %s"):format(NAME, #FRAMES, FRAMES[#FRAMES][1], seq:GetFullName()))
